<?php

declare(strict_types=1);

use Illuminate\Foundation\Testing\DatabaseMigrations;
use Vaulter\Access\Roles\RoleRegistry;
use Vaulter\Access\ValueObjects\Subject;
use Vaulter\Data\Access\GrantInput;
use Vaulter\Data\Drive\UploadSource;
use Vaulter\Enums\Changes\ChangeOperation;
use Vaulter\Tests\Access\AccessTestHelpers;
use Vaulter\Tests\Drive\DriveTestHelpers;
use Vaulter\Tests\TestCase;

uses(TestCase::class, DatabaseMigrations::class);

beforeEach(function (): void {
    config()->set('vaulter.access.permission_driver', 'database');
    $this->drive = DriveTestHelpers::drive();
    $this->shared = $this->drive->folders()->create('shared');
    $this->hidden = $this->drive->folders()->create('hidden');
    AccessTestHelpers::grant($this->shared, RoleRegistry::READER);
    $this->reader = $this->drive->actingAs(AccessTestHelpers::user(1));
});

it('does not resurrect a child renamed after its folder moved out of view', function (): void {
    $folder = $this->drive->folders()->create('docs', $this->shared);
    $file = $this->drive->files()->upload(UploadSource::fromStream(DriveTestHelpers::streamFor('a'), 'a.txt'), $folder);
    $cursor = $this->reader->changes()->startCursor();

    $this->drive->nodes()->move($folder, $this->hidden);
    $this->drive->nodes()->rename($file, 'secret.txt');

    $page = $this->reader->changes()->list($cursor);
    $byId = [];
    foreach ($page->changes as $change) {
        $byId[$change->nodeId] = $change;
    }

    expect($byId)->toHaveKey((string) $folder->id)
        ->and($byId[(string) $folder->id]->operation)->toBe(ChangeOperation::Remove)
        ->and($byId[(string) $folder->id]->node)->toBeNull();

    if (isset($byId[(string) $file->id])) {
        expect($byId[(string) $file->id]->operation)->toBe(ChangeOperation::Remove)
            ->and($byId[(string) $file->id]->node)->toBeNull();
    } else {
        expect($byId)->not->toHaveKey((string) $file->id);
    }

    expect($this->reader->nodes()->find($file->id))->toBeNull();
})->throws(Vaulter\Exceptions\Nodes\NodeNotFoundException::class);

it('projects a directly granted file under a hidden parent as the reader can open it', function (): void {
    $file = $this->drive->files()->upload(UploadSource::fromStream(DriveTestHelpers::streamFor('a'), 'a.txt'), $this->shared);
    $cursor = $this->reader->changes()->startCursor();
    $this->drive->nodes()->move($file, $this->hidden);
    $grant = $this->drive->access()->grant($file, new GrantInput(subject: Subject::ofModel(AccessTestHelpers::user(1)), role: RoleRegistry::READER));

    $page = $this->reader->changes()->list($cursor);
    $ops = [];
    foreach ($page->changes as $change) {
        $ops[] = [$change->nodeId, $change->operation->value, $change->reason?->value, $change->node?->name];
    }

    $found = $this->reader->nodes()->find($file->id);

    expect($ops)->and($found->id)->toBe((string) $file->id)->and($grant)->not->toBeNull();
});
